<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { studentAPI } from '../../api/student'
import type { ApiKey, Model, Organization, Project, RequestedModel } from '../../api/types'
import { APIError } from '../../api/client'
import StatusProgress from '../../components/StatusProgress.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import AppDialog from '../../components/AppDialog.vue'
import ModelForm, { type ModelFormValue } from '../../components/ModelForm.vue'
import LoadingRegion from '../../components/LoadingRegion.vue'
import { useLoadState } from '../../composables/useLoadState'
import { useToast } from '../../composables/useToast'
import { changedApiKeyID } from '../../utils/keyStatusEvents'

const orgs=ref<Organization[]>([]),projects=ref<Project[]>([]),models=ref<Model[]>([]),keys=ref<ApiKey[]>([]),detail=ref<ApiKey|null>(null),secret=ref(''),copied=ref(false),claimConfirm=ref<ApiKey|null>(null),modelDialog=ref(false),error=ref(''),modelQuery=ref('')
const toast=useToast(),loadState=useLoadState()
const form=reactive({organization_id:'',project_id:'',model_ids:[] as string[],requested_models:[] as RequestedModel[],name:'',requested_monthly_credits:'2000.000'})
const custom=reactive<ModelFormValue>({model_id:'',display_name:'',description:null,category:'text',capabilities:[],input_modalities:[],output_modalities:[],context_window:null,max_output_tokens:null,is_common:false,status:'pending_configuration',credit_multiplier:null})
const allCount=computed(()=>form.model_ids.length+form.requested_models.length)
const filteredModels=computed(()=>models.value.filter(model=>!modelQuery.value||`${model.display_name} ${model.model_id} ${model.capabilities.join(' ')}`.toLowerCase().includes(modelQuery.value.toLowerCase())))
const canSubmit=computed(()=>Boolean(form.organization_id&&form.project_id&&form.name.trim()&&form.requested_monthly_credits&&allCount.value>0&&allCount.value<=100))
async function load(){await loadState.run(async()=>{try{[orgs.value,models.value,keys.value]=await Promise.all([studentAPI.organizations(),studentAPI.models(),studentAPI.keys()]);error.value=''}catch(caught){error.value=msg(caught)}})}
async function chooseOrg(){if((form.model_ids.length||form.requested_models.length)&&!confirm('切换组织将清空项目、已选模型和新模型草稿，是否继续？'))return;form.project_id='';form.model_ids=[];form.requested_models=[];projects.value=form.organization_id?await studentAPI.projects(form.organization_id):[]}
function toggleModel(model:Model){const index=form.model_ids.findIndex(value=>value.toLowerCase()===model.model_id.toLowerCase());if(index>=0)form.model_ids.splice(index,1);else if(allCount.value<100)form.model_ids.push(model.model_id)}
function resetCustom(){Object.assign(custom,{model_id:'',display_name:'',description:null,category:'text',capabilities:[],input_modalities:[],output_modalities:[],context_window:null,max_output_tokens:null,is_common:false,status:'pending_configuration',credit_multiplier:null})}
function acceptModel(){error.value='';if(!custom.model_id.trim()||!custom.display_name.trim()||!custom.capabilities.length||!custom.input_modalities.length||!custom.output_modalities.length){error.value='请完整填写模型 ID、显示名称、能力和输入/输出模态';return}const key=custom.model_id.trim().toLowerCase();if(form.model_ids.some(value=>value.toLowerCase()===key)||form.requested_models.some(value=>value.model_id.toLowerCase()===key)){error.value='该模型已在当前白名单中';return}const existing=models.value.find(model=>model.model_id.toLowerCase()===key);if(existing)form.model_ids.push(existing.model_id);else form.requested_models.push({model_id:custom.model_id.trim(),display_name:custom.display_name.trim(),description:custom.description,category:custom.category,capabilities:[...custom.capabilities],input_modalities:[...custom.input_modalities],output_modalities:[...custom.output_modalities],context_window:custom.context_window,max_output_tokens:custom.max_output_tokens});modelDialog.value=false;resetCustom()}
async function submit(){if(!canSubmit.value)return;try{await studentAPI.submit({...form});Object.assign(form,{organization_id:'',project_id:'',model_ids:[],requested_models:[],name:'',requested_monthly_credits:'2000.000'});projects.value=[];await load();toast.success('密钥申请已提交')}catch(caught){error.value=msg(caught)}}
async function show(id:string){try{detail.value=await studentAPI.key(id);secret.value='';copied.value=false}catch(caught){error.value=msg(caught)}}
async function claim(){if(!claimConfirm.value)return;try{const result=await studentAPI.claim(claimConfirm.value.id);secret.value=result.api_key;detail.value=claimConfirm.value;claimConfirm.value=null;await load()}catch(caught){error.value=msg(caught)}}
async function copy(){try{await navigator.clipboard.writeText(secret.value);copied.value=true;toast.success('已复制密钥')}catch{toast.error('复制失败，请手动复制')}}
function closeSecret(){if(secret.value&&!copied.value&&!confirm('密钥尚未复制，关闭后无法再次查看。确定关闭？'))return;secret.value='';detail.value=null}
async function refresh(event:Event){const payload=(event as CustomEvent).detail,changedID=payload?.event==='api_key.status_changed'?changedApiKeyID(keys.value,payload.data):null;await load();if(changedID)await show(changedID)}
function msg(caught:unknown){return caught instanceof APIError?caught.message:'请求失败，请稍后重试'}
onMounted(()=>{void load();window.addEventListener('nebula:refresh',refresh)})
onBeforeUnmount(()=>window.removeEventListener('nebula:refresh',refresh))
</script>

<template><section class="page"><div class="page-heading"><div><p class="eyebrow">STUDENT</p><h1>申请密钥</h1><p class="muted">提交模型白名单与月度 credit 额度申请。</p></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="split" label="正在加载申请"><div class="grid two"><section class="panel"><h2>新申请</h2><form @submit.prevent="submit"><label>1. 组织<select v-model="form.organization_id" @change="chooseOrg"><option value="">请选择</option><option v-for="org in orgs" :key="org.id" :value="org.id">{{org.name}}</option></select></label><label>2. 项目<select v-model="form.project_id" :disabled="!form.organization_id"><option value="">请选择</option><option v-for="project in projects" :key="project.id" :value="project.id" :disabled="project.status!=='active'||!project.has_mentor">{{project.name}} · 项目额度 {{project.monthly_credit_quota}}</option></select></label><fieldset :disabled="!form.project_id"><legend>3. 模型白名单（{{allCount}}/100）</legend><input v-model="modelQuery" placeholder="搜索模型"><div v-for="model in filteredModels" :key="model.id" class="list-row"><div><strong>{{model.display_name}}</strong><p class="muted">{{model.model_id}} · {{model.credit_multiplier??'未配置'}}x</p></div><button type="button" class="button ghost" @click="toggleModel(model)">{{form.model_ids.includes(model.model_id)?'取消':'选择'}}</button></div><div class="chip-list"><span v-for="model in form.requested_models" :key="model.model_id" class="chip">{{model.display_name}} · 新模型</span></div><button type="button" class="button secondary" @click="modelDialog=true;resetCustom()">申请新模型</button></fieldset><label>4. Key 名称<input v-model="form.name" maxlength="128" required></label><label>5. 申请月额度（credits）<input v-model="form.requested_monthly_credits" inputmode="decimal" required><small class="muted">导师初审和老师终审时可调整；按北京时间自然月刷新。</small></label><button class="button primary wide" :disabled="!canSubmit">提交申请</button></form></section><section class="panel"><h2>我的申请</h2><article v-for="key in keys" :key="key.id" class="key-card"><div class="row"><div><strong>{{key.name}}</strong><p class="muted">{{key.project.name}} · 申请 {{key.requested_monthly_credits}} credits</p></div><StatusBadge :status="key.status"/></div><StatusProgress :current="key.progress.current" :completed="key.progress.completed_steps"/><div class="actions"><button class="button ghost" @click="show(key.id)">审核状态</button><button v-if="key.status==='approved'" class="button primary" @click="claimConfirm=key">一次性领取</button></div></article></section></div></LoadingRegion><AppDialog :open="modelDialog" title="申请新模型" @update:open="modelDialog=$event"><ModelForm :model="custom" :show-common="false" submit-label="加入白名单" @submit="acceptModel"/></AppDialog><AppDialog :open="Boolean(claimConfirm)" title="确认一次性领取" @update:open="claimConfirm=$event?claimConfirm:null"><p>完整 API Key 仅显示一次。</p><button class="button primary" @click="claim">确认领取</button></AppDialog><AppDialog :open="Boolean(detail)" :title="secret?'立即保存 API Key':'申请详情'" @update:open="secret?closeSecret():detail=null"><template v-if="secret"><p class="secret">{{secret}}</p><button class="button secondary" @click="copy">{{copied?'已复制':'复制密钥'}}</button></template><template v-else-if="detail"><StatusProgress :current="detail.progress.current" :completed="detail.progress.completed_steps"/><p>学生申请 {{detail.requested_monthly_credits}} · 导师审核 {{detail.mentor_monthly_credits??'—'}} · 最终额度 {{detail.monthly_credits??'—'}} credits</p><p>{{detail.models.map(model=>`${model.model_id} (${model.credit_multiplier??'未配置'}x)`).join('、')}}</p></template></AppDialog></section></template>
